        tests++;GatewayBindingConfig cfg=GatewayBindingConfig.parse(config(),saved);Authority authority=new Authority(saved);Storage store=new Storage();GatewaySequenceStore sequences=new GatewaySequenceStore(store);List<GatewayGrantIssuer.Packet> packets=GatewayGrantIssuer.issue(authority,saved,cfg,sequences,WALL,false,()->true);check(packets.size()==4&&authority.signed==4&&store.writes==1);for(int i=0;i<4;i++){GatewayGrantIssuer.Packet packet=packets.get(i);check(packet.body.length==192&&packet.envelope.length==209+packet.signature.length);check(authority.verified(packet.body,packet.signature));ByteBuffer body=ByteBuffer.wrap(packet.body);check(body.getLong(56)==i%2+1);check(body.getLong(72)-body.getLong(64)==30);check(GatewayGrantCodec.scopedBinding(packet.body,GROUP,3,packet.target));check(!GatewayGrantCodec.scopedBinding(packet.body,GROUP,3,packet.target.equals(NODE1)?NODE2:NODE1));byte[] changed=packet.body.clone();changed[112]^=1;check(!authority.verified(changed,packet.signature));}check(saved.network==null&&!saved.live);rejects(()->GatewayGrantIssuer.issue(authority,saved,cfg,sequences,WALL,true,()->true));
