        tests++;for(JSONObject invalid:new JSONObject[]{config().put("epoch",4),config().put("ownerPin",PEER),config().put("autoResume",true),config().put("nodes",new JSONArray()),config().put("bindings",new JSONArray())})rejects(()->GatewayBindingConfig.parse(invalid,saved));JSONObject duplicate=config();duplicate.getJSONArray("bindings").getJSONObject(1).put("phonePin",OWNER);rejects(()->GatewayBindingConfig.parse(duplicate,saved));JSONObject unknown=config();unknown.getJSONArray("bindings").getJSONObject(1).put("phonePin","DD".repeat(32));rejects(()->GatewayBindingConfig.parse(unknown,saved));JSONObject foreign=config();foreign.getJSONArray("bindings").getJSONObject(0).put("ipv4","192.168.1.2");rejects(()->GatewayBindingConfig.parse(foreign,saved));rejects(()->cfg.liveOwner(saved));cfg.liveOwner(live);GatewayOwnerAuthority.Scope wrongAddress=new GatewayOwnerAuthority.Scope(source,"12345678-1234-1234-1234-123456789abc",OWNER,GROUP,3,5,Arrays.asList(OWNER,PEER),source,"10.77.0.11",24,true);rejects(()->cfg.liveOwner(wrongAddress));
        tests++;Authority changing=new Authority(live);GatewaySequenceStore reserved=new GatewaySequenceStore(new Storage());CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);changing.before=()->{entered.countDown();if(!release.await(2,TimeUnit.SECONDS))throw new java.io.IOException("test timeout");};AtomicReference<Object> outcome=new AtomicReference<>();Thread signer=new Thread(()->{try{outcome.set(GatewayGrantIssuer.issue(changing,live,cfg,reserved,WALL,true,()->true));}catch(Exception rejected){outcome.set(rejected);}});signer.start();check(entered.await(2,TimeUnit.SECONDS));changing.current.set(scope(source,4,5,true));release.countDown();signer.join(2000);check(!signer.isAlive()&&outcome.get() instanceof Exception);check(changing.signed==1);Authority replacement=new Authority(live);replacement.before=()->replacement.current.set(scope(new Object(),3,5,true));rejects(()->GatewayGrantIssuer.issue(replacement,live,cfg,new GatewaySequenceStore(new Storage()),WALL,true,()->true));Authority revoked=new Authority(live);revoked.current.set(new GatewayOwnerAuthority.Scope(source,"12345678-1234-1234-1234-123456789abc",OWNER,GROUP,3,5,Collections.singleton(OWNER),source,"10.77.0.10",24,true));rejects(()->GatewayGrantIssuer.issue(revoked,live,cfg,new GatewaySequenceStore(new Storage()),WALL,true,()->true));check(revoked.signed==0);
        tests++;GatewaySessionFence fence=new GatewaySessionFence();GatewaySessionFence.Session a=fence.start("a".repeat(32),100,1000);check(a.healthy(101,1001)&&a.due(101));a.renewed(101);check(!a.due(101+9999)&&a.due(101+10000));check(fence.stop(a.id,a.generation));GatewaySessionFence.Session b=fence.start(a.id,200,2000);check(!fence.stop(a.id,a.generation)&&fence.owns(b));a.deny();check(fence.owns(b));check(!b.healthy(201,1999));check(!fence.owns(b));check(fence.stop(b.id,b.generation));GatewaySessionFence.Session expired=fence.start("c".repeat(32),300,3000);check(!expired.healthy(expired.deadline,3000+GatewaySessionFence.LIMIT_MS));check(!expired.healthy(301,3001));
        tests++;GatewaySessionFence.Session ordered=new GatewaySessionFence.Session("d".repeat(32),1,100,1000);CountDownLatch clockEntered=new CountDownLatch(1),clockRelease=new CountDownLatch(1);AtomicBoolean secondSampled=new AtomicBoolean(),one=new AtomicBoolean(),two=new AtomicBoolean();Thread firstClock=new Thread(()->one.set(ordered.healthy(new GatewaySessionFence.Clock(){public long elapsed(){clockEntered.countDown();try{if(!clockRelease.await(2,TimeUnit.SECONDS))throw new AssertionError();}catch(Exception failure){throw new AssertionError(failure);}return 101;}public long wall(){return 1001;}})));Thread secondClock=new Thread(()->two.set(ordered.healthy(new GatewaySessionFence.Clock(){public long elapsed(){secondSampled.set(true);return 102;}public long wall(){return 1002;}})));firstClock.start();check(clockEntered.await(2,TimeUnit.SECONDS));secondClock.start();Thread.sleep(20);check(!secondSampled.get());clockRelease.countDown();firstClock.join(2000);secondClock.join(2000);check(one.get()&&two.get());
