        tests++;Storage configStorage=new Storage();GatewayConfigStore configurations=new GatewayConfigStore(configStorage);check(configurations.current()==null);String operation="e".repeat(32);GatewayConfigStore.Record configured=configurations.save(saved,config(),0,operation);check(configured.revision==1&&configStorage.writes==1);check(configurations.save(saved,config(),0,operation).revision==1&&configStorage.writes==1);rejects(()->configurations.save(saved,config(),0,"f".repeat(32)));JSONObject changed=config();changed.getJSONArray("bindings").getJSONObject(0).put("mac","020000000012");rejects(()->configurations.save(saved,changed,0,operation));check(configStorage.writes==1);GatewayConfigStore reloadConfig=new GatewayConfigStore(configStorage);reloadConfig.current().checked(scope(source,3,9,false));rejects(()->reloadConfig.current().checked(scope(source,4,9,false)));GatewayOwnerAuthority.Scope removed=new GatewayOwnerAuthority.Scope(source,saved.process,OWNER,GROUP,3,9,Collections.singleton(OWNER),null,null,0,false);rejects(()->reloadConfig.current().checked(removed));check(reloadConfig.save(saved,config(),1,"f".repeat(32)).revision==2);rejects(()->reloadConfig.save(saved,config(),0,operation));
        tests++;FileStorage configuredFile=new FileStorage(directory.resolve("checked-config.json"));GatewayConfigStore durableConfig=new GatewayConfigStore(configuredFile);durableConfig.save(saved,config(),0,operation);GatewayConfigStore reopenedConfig=new GatewayConfigStore(configuredFile);check(reopenedConfig.current().revision==1);check(reopenedConfig.current().config.bindings.size()==2);GatewayOwnerAuthority.Scope newProcess=new GatewayOwnerAuthority.Scope(new Object(),"87654321-1234-1234-1234-123456789abc",OWNER,GROUP,3,0,Arrays.asList(OWNER,PEER),null,null,0,false);reopenedConfig.current().checked(newProcess);rejects(()->reopenedConfig.save(newProcess,config(),0,operation));check(authority.signed==4);
